<script setup>
import { computed, ref, watch } from 'vue';
const props=defineProps(['api','params']);
const kind=computed(()=>props.params?.kind||'chart');
const note=ref(props.params?.note||'');watch(()=>props.params?.note,v=>note.value=v||'');
function updateNote(){props.api.updateParameters({note:note.value});}
const candles=Array.from({length:100},(_,i)=>{const base=120-Math.sin(i/13)*38-i*.32;const open=base+Math.sin(i*3)*7,close=base+Math.cos(i*2)*8;return{x:15+i*7,open,close,high:Math.min(open,close)-6,low:Math.max(open,close)+7};});
const coins=['ETH','SOL','XRP','DOGE','ADA','AVAX','LINK','SUI','TON','DOT','BTC','LTC'];
const rows=Array.from({length:15},(_,i)=>({price:(80634.4+i*1.7).toFixed(1),amount:(.03+(i%7)*.031).toFixed(3),total:(120+i*43.78).toFixed(2)}));
</script>
<template>
<div class="panel-body" :class="{ 'panel-body--chart': kind === 'chart' }">
<template v-if="kind==='chart'"><div class="chart-tools"><span>1分</span><span>5分</span><b>15分</b><span>1小时</span><span>4小时</span><span>1日</span><span class="right">指标　⚙　⛶</span></div><div class="ohlc">BTCUSDT · 15 · 模拟数据 <span class="green">开 80,496.2 高 80,645.8 低 80,496.1 收 80,634.4</span></div><svg class="chart" viewBox="0 0 760 250" preserveAspectRatio="none"><defs><pattern id="grid" width="76" height="50" patternUnits="userSpaceOnUse"><path d="M76 0H0V50" fill="none" stroke="#232526" stroke-width="1"/></pattern></defs><rect width="760" height="250" fill="url(#grid)"/><g v-for="c in candles" :stroke="c.close<c.open?'#27AD75':'#F0616D'" :fill="c.close<c.open?'#27AD75':'#F0616D'"><line :x1="c.x" :x2="c.x" :y1="c.high" :y2="c.low"/><rect :x="c.x-2" :y="Math.min(c.open,c.close)" width="4" :height="Math.max(1,Math.abs(c.open-c.close))"/><rect :x="c.x-2" :y="240-(c.low-c.high)" width="4" :height="c.low-c.high" opacity=".35"/></g><line x1="0" x2="760" y1="76" y2="76" stroke="#27AD75" stroke-dasharray="3 4"/></svg><div class="time-axis">06:00 <span>09:00</span><span>12:00</span><span>15:00</span><span>18:00</span></div></template>
<template v-else-if="kind==='book'||kind==='trades'"><div class="table-head"><span>价格 (USDT)</span><span>数量 (BTC)</span><span>累计</span></div><div v-for="(r,i) in rows" class="book-row" :style="{'--depth':`${20+(i*17)%80}%`}"><span :class="i<7?'red':'green'">{{r.price}}</span><span>{{r.amount}}</span><span>{{r.total}}</span></div></template>
<template v-else-if="kind==='markets'"><div class="table-head"><span>交易对</span><span>最新价格</span><span>涨跌幅</span></div><div v-for="(coin,i) in coins" class="market-row"><div><b>{{coin}}<small>/USDT</small></b><label>成交量 {{(90+i*27.1).toFixed(1)}}M</label></div><span>{{(2024.6/(i+1)).toFixed(2)}}</span><span :class="i%3?'green':'red'">{{i%3?'+':'-'}}{{(1.2+i*.31).toFixed(2)}}%</span></div></template>
<template v-else-if="kind==='trade'"><div class="trade-pad"><div class="segmented"><b>开仓</b><span>平仓</span></div><p class="muted">全仓 <span class="right green">10x</span></p><div class="trade-tabs">限价委托　 <span class="muted">市价委托</span></div><label>价格 (USDT)<input value="80634.4" disabled></label><label>数量 (BTC)<input placeholder="仅供展示" disabled></label><div class="slider"></div><p class="muted">可用 <span class="right">模拟账户 10,000 USDT</span></p><div class="trade-buttons"><button disabled>买入 / 做多</button><button disabled>卖出 / 做空</button></div><p class="notice">此示例不含登录、API 密钥或下单功能。</p></div></template>
<template v-else-if="kind==='notes'"><div class="note-pad"><label>你的自定义组件示例</label><textarea v-model="note" @input="updateNote" placeholder="输入研究笔记，随布局保存在本机…"></textarea></div></template>
<template v-else><div class="orders"><div class="order-filters">全部交易对　 <span class="muted">仅显示当前交易对</span></div><table><thead><tr><th>交易品种</th><th>方向</th><th>数量</th><th>委托价格</th><th>状态</th></tr></thead><tbody><tr><td>BTCUSDT 永续 <small>模拟</small></td><td class="green">买入开多</td><td>0.010 BTC</td><td>78,500.0</td><td>{{kind==='positions'?'持仓展示':'待成交展示'}}</td></tr></tbody></table><p class="notice">数据仅用于验证布局和组件生命周期，不表示真实委托或持仓。</p></div></template>
</div>
</template>
